import type { Athlete, ArchetypeId, SportId } from '../engine/types';
import { HABITATS } from './habitats';

// Base des espèces animales (le fichier garde son nom d'AthletiCards).
// - fame (0-100) : célébrité de l'espèce. Elle fixe la rareté.
// - level (0-100) : puissance naturelle. Elle place la note de la carte dans la plage de sa rareté.
// - country : pays emblématique de l'espèce (pays de découverte pour les fossiles ; XO = océans, XW = monde entier).
// - role : milieu de vie (période géologique pour la préhistoire).
// Les faits restent volontairement sobres et vérifiables.

type Extra = Partial<Omit<Athlete, 'id' | 'first' | 'last' | 'sport' | 'archetype' | 'role' | 'country' | 'fame' | 'level' | 'fact'>>;

function a(
  id: string,
  first: string,
  last: string,
  sport: SportId,
  archetype: ArchetypeId,
  role: string,
  country: string,
  fame: number,
  level: number,
  fact: string,
  extra: Extra = {},
): Athlete {
  return { id, first, last, sport, archetype, role, country, fame, level, fact, ...extra };
}

/** Une espèce : tout le nom est dans « last ». */
function x(
  id: string,
  name: string,
  sport: SportId,
  archetype: ArchetypeId,
  role: string,
  country: string,
  fame: number,
  level: number,
  fact: string,
  extra: Extra = {},
): Athlete {
  return a(id, '', name, sport, archetype, role, country, fame, level, fact, extra);
}

/** Version Prime : un individu célèbre de l'espèce. */
const P = (year: string, note: string) => ({ prime: { year, note } });

/** Espèce disparue (carte Icône), avec l'année de sa disparition si elle est connue. */
const D = (died?: number) => ({ retired: true as const, ...(died ? { died } : {}) });

/** Nom scientifique. */
const L = (latin: string) => ({ latin });

